// --- Physics (movement + wall/paddle/brick bounces) -----------------------

// True if the ball box (half-size `r`) swept from `prev` to `ball` crosses the
// brick. Exact test: the center path is raycast against the brick inflated by
// `r` (Minkowski sum of the box and the path segment). Catches a step that is
// longer than the brick itself (tunneling, see D5 of .scratch/to_fix.md).
function sweptCrosses(prev, ball, brick) {
  const r = ball.r;
  const x0 = brick.x - r;
  const x1 = brick.x + brick.w + r;
  const y0 = brick.y - r;
  const y1 = brick.y + brick.h + r;
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;

  let tMin = 0;
  let tMax = 1;
  if (Math.abs(dx) > 1e-9) {
    let t1 = (x0 - prev.x) / dx;
    let t2 = (x1 - prev.x) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tMin = Math.max(tMin, t1);
    tMax = Math.min(tMax, t2);
  } else if (prev.x < x0 || prev.x > x1) {
    return false; // no horizontal motion and the center is outside the slab
  }
  if (Math.abs(dy) > 1e-9) {
    let t1 = (y0 - prev.y) / dy;
    let t2 = (y1 - prev.y) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tMin = Math.max(tMin, t1);
    tMax = Math.min(tMax, t2);
  } else if (prev.y < y0 || prev.y > y1) {
    return false;
  }
  // tMin > 0: the path enters the brick strictly after the start, i.e. the
  // ball was NOT already overlapping at `prev` (a ball leaving a brick is not
  // a hit).
  return tMin > 1e-9 && tMin <= tMax;
}

// Resolves ball-vs-bricks collisions for the current step. `prev` is the ball
// position at the start of the step (before movement).
//
// Destroys every live brick the ball's box overlaps now or crossed during the
// step (swept), then bounces the ball EXACTLY ONCE per axis: two bricks hit in
// the same pass on a grid seam must not cancel two flips (D4). The axis is the
// one of dominant movement (the face the ball entered through); equal movement
// or an already-overlapping ball falls back to the least-penetration axis, and
// equal penetration on both axes is a corner: both velocities flip (D2b).
function resolveBricks(state, prev) {
  const { ball } = state;
  const r = ball.r;

  const hit = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick) || sweptCrosses(prev, ball, brick)) {
      hit.push(brick);
    }
  }
  if (hit.length === 0) return;

  // Score and destroy every hit brick (one pass, alive flag prevents double
  // counting — same semantics as the old frame() loop).
  for (const brick of hit) {
    if (!brick.alive) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // Union of the hit bricks: the surface the ball bounces off.
  const u = {
    x: Math.min(...hit.map((b) => b.x)),
    y: Math.min(...hit.map((b) => b.y)),
    x2: Math.max(...hit.map((b) => b.x + b.w)),
    y2: Math.max(...hit.map((b) => b.y + b.h)),
  };

  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;

  // Penetration of the ball box into the union, at the overlap state.
  const penetration = (ox, oy) => ({
    px: Math.min(u.x2, ball.x + r) - Math.max(u.x, ball.x - r),
    py: Math.min(u.y2, ball.y + r) - Math.max(u.y, ball.y - r),
