  const moveX = Math.abs(dx);
  const moveY = Math.abs(dy);
  const horizontal = () => {
    if (dx < 0) ball.x = u.x2 + r;
    else ball.x = u.x - r;
    ball.vx = -ball.vx;
  };
  const vertical = () => {
    if (dy < 0) ball.y = u.y2 + r;
    else ball.y = u.y - r;
    ball.vy = -ball.vy;
  };

  if (moveY > moveX) {
    vertical();
  } else if (moveX > moveY) {
    horizontal();
  } else if (px < py) {
