// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prev = { x: ball.x, y: ball.y };

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept test on the path: the ball bounces whenever its path
  // crosses the paddle top edge, whatever the step length. A point-in-slab
  // test would let a step longer than the paddle thickness (12 px) skip the
  // slab and fall through (D6a/D6b of .scratch/to_fix.md).
  if (
    ball.vy > 0 &&
    prev.y + ball.r <= paddle.y &&
    ball.y + ball.r >= paddle.y &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks — once per pass per axis (the bounce the old frame() loop lacked,
  // debt #1/#2 of the header comment).
  resolveBricks(state, prev);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

