import('./game/neon.js').then((m) => {
  const state = m.createState(1);
  let seed = 42;
  const rnd = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
  // exact swept test, same as the game's (segment vs brick inflated by r)
  const crosses = (px, py, bx, by, brick) => {
    const r = 7;
    const x0 = brick.x - r, x1 = brick.x + brick.w + r, y0 = brick.y - r, y1 = brick.y + brick.h + r;
    const dx = bx - px, dy = by - py;
    let tMin = 0, tMax = 1;
    if (Math.abs(dx) > 1e-9) { let t1 = (x0 - px) / dx, t2 = (x1 - px) / dx; if (t1 > t2) [t1, t2] = [t2, t1]; tMin = Math.max(tMin, t1); tMax = Math.min(tMax, t2); }
    else if (px < x0 || px > x1) return false;
    if (Math.abs(dy) > 1e-9) { let t1 = (y0 - py) / dy, t2 = (y1 - py) / dy; if (t1 > t2) [t1, t2] = [t2, t1]; tMin = Math.max(tMin, t1); tMax = Math.min(tMax, t2); }
    else if (py < y0 || py > y1) return false;
    return tMin > 1e-9 && tMin <= tMax;
  };
  let passThrough = 0, firstPass = null;
  for (let i = 0; i < 300000; i++) {
    const dt = 0.016;
    if (i % 60 === 0) state.paddle.x = Math.max(0, Math.min(m.WIDTH - state.paddle.w, state.ball.x - state.paddle.w / 2 + (rnd() * 72 - 36)));
    const prev = { x: state.ball.x, y: state.ball.y };
    const lost = m.step(state, dt);
    if (lost) { state.lives -= 1; if (state.lives <= 0) { state.lives = 3; state.bricks = m.makeBricks(state.level); } state.ball = m.createState(state.level).ball; }
    // a live brick whose swept path the ball crossed MUST have been destroyed
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      const overlapped = m.collides({ x: prev.x, y: prev.y, r: 7 }, brick) || m.collides(state.ball, brick);
      const crossed = crosses(prev.x, prev.y, state.ball.x, state.ball.y, brick);
      if (crossed || overlapped) { passThrough++; if (!firstPass) firstPass = { f: i, brick: [brick.x, brick.y], ball: [state.ball.x.toFixed(1), state.ball.y.toFixed(1)], prev: [prev.x.toFixed(1), prev.y.toFixed(1)] }; }
    }
    if (state.bricks.every((br) => !br.alive)) { state.level++; state.bricks = m.makeBricks(state.level); state.ball = m.createState(state.level).ball; }
  }
  console.log('live bricks crossed/overlapped by the ball path but NOT destroyed:', passThrough, firstPass ? JSON.stringify(firstPass) : 'none');
});
