  // Penetration of the ball box into the union at `prev`: meaningful only for
  // a diagonal approach (|dx| === |dy|), where the overlap state at `prev`
  // decides the corner rule. For every other approach the face is the one of
  // dominant movement (the face the ball entered through), which also gives
  // the correct bounce when a previous frame's reposition left the ball
  // touching a neighbour row (the 8 px grid gap is smaller than the 14 px
  // ball, so a face-touch position always reaches into the next row).
  const penetration = (x, y) => ({
    px: Math.min(u.x2, x + r) - Math.max(u.x, x - r),
    py: Math.min(u.y2, y + r) - Math.max(u.y, y - r),
  });

  const moveX = Math.abs(dx);
  const moveY = Math.abs(dy);
  const horizontal = () => {
    if (dx < 0) ball.x = u.x2 + r;
    else ball.x = u.x - r;
    ball.vx = -ball.vx;
  };
  const vertical = () => {
    if (dy < 0) ball.y = u.y2 + r;
    else ball.y = u.y - r;
    ball.vy = -ball.vy;
  };

  if (moveY > moveX) {
    vertical();
  } else if (moveX > moveY) {
    horizontal();
  } else {
    // Diagonal entry: the axis of least penetration decides; equal
    // penetration on both axes is a corner — both velocities flip.
    const { px, py } = penetration(prev.x, prev.y);
    if (px < py) {
      horizontal();
    } else if (py < px) {
      vertical();
    } else {
      horizontal();
      vertical();
    }
  }
}

